<!doctype html><html><head><meta charset=utf8><meta name=viewport content="width=device-width,initial-scale=1,viewport-fit=cover"><style>:root{color-scheme:light;box-sizing:border-box;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}html{scroll-padding-top:env(safe-area-inset-top,0px)}body{margin:0;padding:0;font:14px -apple-system,BlinkMacSystemFont,sans-serif;background:#fff;color:#000}img{max-width:100%}[hidden]:not([hidden=until-found i]){display:none!important}</style></head><body>
<title>Underserved Islands Heat Map</title>
<meta name="claude:viewport-fit-sides" content="cover">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Archivo:wdth,wght@75..100,500..800&family=Public+Sans:wght@400;600;700&family=JetBrains+Mono:wght@400;600&display=swap">
<style>
/* Layout: app shell — brand bar with section nav on top; filters, tier cards and tabbed lists on the left; the heat map in its own card on the right with lens bar, report button, map controls and legend. Phones stack map over list. */
:root{
  --sea:#e9f0f2; --sea-2:#dbe6ea; --reef:#c3d3db; --reef-edge:#9fb6c2;
  --paper:#f8fafa; --ink:#0f2a33; --muted:#557079; --line:#d2dee2; --chip:#e7eff1;
  --accent:#0b6e7d;
  --t1:#b3123b; --t2:#df5f22; --t3:#d9a521; --t0:#3d8c7d; --tna:#9aa7ab;
  --rtl:#0b6e7d; --cfn:#7a4fc2; --h0:#e6efe4; --h1:#ffd978; --h2:#f39a3d; --h3:#d43d2a; --h4:#7a0f2e; --land:#efe6cf; --land-edge:#b9a77d; --reefline:#9fb6c2;
  --f-disp:"Archivo","Arial Narrow",Arial,sans-serif;
  --f-body:"Public Sans","Segoe UI",system-ui,sans-serif;
  --f-mono:"JetBrains Mono",ui-monospace,Menlo,monospace;
}
@media (prefers-color-scheme: dark){:root:not([data-theme="light"]){
  --sea:#0b1c22; --sea-2:#12272f; --reef:#1b3540; --reef-edge:#2d4e5b;
  --paper:#0f2129; --ink:#e4eff1; --muted:#8ea9b1; --line:#22404a; --chip:#173039;
  --accent:#4fc3d2; --rtl:#4fc3d2; --cfn:#b79cf2; --t1:#ff4f74; --t2:#ff8a4c; --t3:#f2c64d; --t0:#5cc4ae; --tna:#6d7f85; --h0:#2f4a45; --land:#5b5440; --land-edge:#8a7d59; --reefline:#2d4e5b; color-scheme:dark}}
:root[data-theme="dark"]{
  --sea:#0b1c22; --sea-2:#12272f; --reef:#1b3540; --reef-edge:#2d4e5b;
  --paper:#0f2129; --ink:#e4eff1; --muted:#8ea9b1; --line:#22404a; --chip:#173039;
  --accent:#4fc3d2; --rtl:#4fc3d2; --cfn:#b79cf2; --t1:#ff4f74; --t2:#ff8a4c; --t3:#f2c64d; --t0:#5cc4ae; --tna:#6d7f85; --h0:#2f4a45; --land:#5b5440; --land-edge:#8a7d59; --reefline:#2d4e5b; color-scheme:dark}
html,body{height:100%}
body{background:var(--paper);color:var(--ink);font:15px/1.45 var(--f-body)}
*{box-sizing:border-box}
.shell{height:calc(100vh - 52px);display:flex;flex-direction:column;padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px))}
.topbar{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;padding-block:12px;border-bottom:1px solid var(--line)}
.brand{display:flex;align-items:baseline;gap:10px;min-width:0}
.brand b{font:800 24px/1 var(--f-disp);font-stretch:80%;letter-spacing:.01em;white-space:nowrap}
.brand span{font-size:12.5px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.nav{display:flex;gap:4px;flex-wrap:wrap}
.nav button{font:600 13.5px var(--f-body);padding:7px 13px;border-radius:999px;border:0;background:transparent;color:var(--muted);cursor:pointer}
.nav button:hover{color:var(--ink);background:var(--chip)}
.nav button[aria-current="page"]{background:var(--chip);color:var(--ink)}
.app{flex:1;min-height:0;display:grid;grid-template-columns:minmax(360px,44%) 1fr;gap:16px;padding-block:14px}
.panel{display:flex;flex-direction:column;min-height:0;min-width:0}
.head{display:flex;flex-direction:column;gap:10px;padding-bottom:10px}
.filters{display:grid;grid-template-columns:1fr 1.3fr;gap:8px}
.search{position:relative}
.search input{padding-left:32px}
.search svg{position:absolute;left:10px;top:50%;transform:translateY(-50%);width:15px;height:15px;stroke:var(--muted);fill:none;stroke-width:2}
.mapcard{display:flex;flex-direction:column;min-height:0;min-width:0;border:1px solid var(--line);border-radius:12px;overflow:hidden;background:var(--paper)}
.tools{display:grid;grid-template-columns:1fr auto;gap:8px;align-items:center}
.tools .btn{white-space:nowrap}
.maphead{display:flex;flex-wrap:wrap;gap:8px 10px;align-items:center;padding:10px 12px;border-bottom:1px solid var(--line)}
.maphead .chips{flex:1 1 auto}
.maphead select{width:auto;max-width:240px;padding:6px 8px;font-size:13px}
.maphead .lensnote{flex-basis:100%;min-height:0}
.rlist .ln{width:22px;height:0;border-top:3px solid var(--c);margin-top:9px;display:block}
.rlist button{grid-template-columns:22px 1fr auto!important;align-items:start!important}
.rlist .code{font:12px var(--f-mono);color:var(--muted);margin-left:6px}
h1{font:800 30px/1 var(--f-disp);font-stretch:80%;letter-spacing:.005em;margin:0;text-wrap:balance}
.sub{color:var(--muted);font-size:13px;margin:4px 0 0}
.lbl{font:700 12px var(--f-disp);font-stretch:85%;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);margin:0}
.chips{display:flex;flex-wrap:wrap;gap:6px}
.chip{font:600 13px var(--f-body);padding:5px 11px;border-radius:999px;border:1px solid var(--line);background:var(--chip);color:var(--ink);cursor:pointer}
.chip[aria-pressed="true"]{background:var(--ink);border-color:var(--ink);color:var(--paper)}
.chip:focus-visible,button:focus-visible,select:focus-visible,input:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
select,input[type=search]{font:inherit;font-size:14px;padding:8px 10px;border-radius:8px;border:1px solid var(--line);background:var(--sea);color:var(--ink);width:100%;min-width:0}
.row{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.lensnote{font-size:12.5px;color:var(--muted);margin:0}
.tiers{display:grid;grid-template-columns:repeat(5,1fr);gap:4px}
.tierbtn{font:inherit;text-align:left;padding:9px 10px;border-radius:10px;border:1px solid var(--line);background:var(--paper);color:var(--ink);cursor:pointer;min-width:0}
.tierbtn b{display:block;font:800 24px/1 var(--f-disp);font-variant-numeric:tabular-nums}
.tierbtn span{display:block;font-size:11px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.tierbtn i{display:block;height:4px;border-radius:2px;margin-bottom:8px;background:var(--c)}
.tierbtn[aria-pressed="false"]{opacity:.4}
.body{flex:1;min-height:0;overflow:auto;border-top:1px solid var(--line);padding-block:6px 18px}
.list{list-style:none;margin:0;padding:0}
.list button{all:unset;box-sizing:border-box;display:grid;grid-template-columns:10px 1fr auto;gap:10px;align-items:center;width:100%;padding:8px 6px;border-radius:6px;cursor:pointer}
.list button:hover,.list button:focus-visible{background:var(--chip)}
.list .sw{width:10px;height:10px;border-radius:50%;background:var(--c)}
.list .t{font-weight:600;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.list .t small{font-weight:400;color:var(--muted);margin-left:6px}
.list .n{font:12px var(--f-mono);color:var(--muted);font-variant-numeric:tabular-nums}
.actions{display:flex;flex-wrap:wrap;gap:8px}
.btn{font:700 13px var(--f-body);padding:8px 12px;border-radius:8px;border:1px solid var(--ink);background:var(--ink);color:var(--paper);cursor:pointer}
.btn.ghost{background:transparent;color:var(--ink);border-color:var(--line)}
.back{all:unset;cursor:pointer;color:var(--accent);font-size:13px;padding:6px 0}
.detail h2{font:800 30px/1.02 var(--f-disp);font-stretch:85%;margin:6px 0 2px}
.pill{display:inline-flex;align-items:center;gap:6px;font:700 12px var(--f-body);padding:3px 9px;border-radius:999px;color:#fff;background:var(--c)}
.facts{display:grid;grid-template-columns:auto 1fr;gap:5px 14px;font-size:14px;margin:12px 0}
.facts dt{color:var(--muted)} .facts dd{margin:0;min-width:0}
.mono{font-family:var(--f-mono);font-size:13px;font-variant-numeric:tabular-nums}
.dims{display:grid;grid-template-columns:1fr 1fr;gap:6px;margin:10px 0}
.dim{border:1px solid var(--line);border-radius:8px;padding:7px 9px;min-width:0}
.dim span{display:block;font-size:11.5px;color:var(--muted)}
.dim b{font:700 15px var(--f-disp);font-stretch:90%}
.dim.High b{color:var(--t1)} .dim.Medium b{color:var(--t2)} .dim.Low b{color:var(--t0)}
.why{font-size:13.5px;margin:8px 0;padding:8px 10px;border-radius:6px;background:var(--chip)}
.foot{font-size:12px;color:var(--muted);margin-top:14px;border-top:1px solid var(--line);padding-top:10px}
.foot p{margin:0 0 6px}

#map{position:relative;flex:1;min-height:0;background:var(--sea);min-width:0}
.legend{position:absolute;z-index:1000;right:max(12px,env(safe-area-inset-right,0px));bottom:16px;background:var(--paper);border:1px solid var(--line);border-radius:10px;padding:10px 12px;font-size:12px;min-width:210px;box-shadow:0 6px 18px rgba(0,0,0,.12)}
.legend .classes{display:grid;grid-template-columns:repeat(10,1fr);gap:0;margin:8px 0 3px;border:1px solid var(--ink)}
.legend .classes i{height:12px;display:block}
.legend .cticks{display:flex;justify-content:space-between;font:11px var(--f-mono);color:var(--muted);font-variant-numeric:tabular-nums}
.legend .cticks span:last-child{text-align:right}
.legend .cats{display:grid;grid-template-columns:auto 1fr auto;gap:5px 8px;align-items:center;margin-top:8px}
.legend .cats i{width:14px;height:10px;border:1px solid var(--ink);display:block}
.legend .cats .n{font:11px var(--f-mono);color:var(--muted);text-align:right}
.legend .src{margin-top:8px;font-size:10.5px;color:var(--muted)}
.legend .na{display:inline-flex;gap:5px;align-items:center;color:var(--muted);margin-top:6px}.legend .na i{width:9px;height:9px;border-radius:50%;background:var(--tna);display:inline-block}
.legend .ends{display:flex;justify-content:space-between;color:var(--muted)}
.legend .keys{display:flex;flex-wrap:wrap;gap:4px 10px;margin-top:8px}
.legend .keys span{display:inline-flex;gap:5px;align-items:center}
.legend .keys i{width:9px;height:9px;border-radius:50%;background:var(--c);display:inline-block}
.legend .row2{display:flex;justify-content:space-between;gap:8px;align-items:center}
.legend label{display:flex;gap:6px;align-items:center;color:var(--muted);cursor:pointer}

/* Leaflet core (inlined) */
.leaflet-pane,.leaflet-tile,.leaflet-marker-icon,.leaflet-tile-container,.leaflet-pane>svg,.leaflet-pane>canvas,.leaflet-zoom-box,.leaflet-layer{position:absolute;left:0;top:0}
.leaflet-container{overflow:hidden;-webkit-tap-highlight-color:transparent;font-family:var(--f-body);background:var(--sea)}
.leaflet-container.leaflet-touch-drag{touch-action:none}
.leaflet-container .leaflet-overlay-pane svg{max-width:none!important;max-height:none!important}
.leaflet-pane{z-index:400}.leaflet-overlay-pane{z-index:400}.leaflet-marker-pane{z-index:600}.leaflet-tooltip-pane{z-index:650}
.leaflet-map-pane canvas{z-index:100}.leaflet-map-pane svg{z-index:200}
.leaflet-pane>svg path{pointer-events:none}
.leaflet-pane>svg path.leaflet-interactive{pointer-events:visiblePainted;pointer-events:auto}
.leaflet-zoom-animated{transform-origin:0 0}
.leaflet-zoom-anim .leaflet-zoom-animated{transition:transform .25s cubic-bezier(0,0,.25,1)}
.leaflet-zoom-anim .leaflet-zoom-hide{visibility:hidden}
.leaflet-interactive{cursor:pointer}
.leaflet-grab{cursor:grab}.leaflet-dragging .leaflet-grab,.leaflet-dragging .leaflet-interactive{cursor:grabbing}
.leaflet-control{position:relative;z-index:800;pointer-events:auto;float:left;clear:both}
.leaflet-top,.leaflet-bottom{position:absolute;z-index:1000;pointer-events:none}
.leaflet-top{top:0}.leaflet-right{right:0}.leaflet-bottom{bottom:0}.leaflet-left{left:0}
.leaflet-top .leaflet-control{margin-top:12px}.leaflet-left .leaflet-control{margin-left:12px}
.leaflet-bar{border-radius:8px;overflow:hidden;border:1px solid var(--line);background:var(--paper)}
.leaflet-bar a{display:block;width:34px;height:34px;line-height:32px;text-align:center;text-decoration:none;color:var(--ink);font-size:20px;background:var(--paper)}
.leaflet-bar a+a{border-top:1px solid var(--line)}
.leaflet-tooltip{position:absolute;white-space:nowrap;pointer-events:none;background:var(--paper);color:var(--ink);border:1px solid var(--line);border-radius:6px;padding:4px 8px;font-size:13px;box-shadow:0 4px 12px rgba(0,0,0,.15)}
.leaflet-tooltip-right{margin-left:8px}.leaflet-tooltip-left{margin-left:-8px}
.atoll-shape{fill:var(--reef);fill-opacity:.35;stroke:none}
.atoll-label{font:600 11px var(--f-disp);font-stretch:85%;letter-spacing:.28em;text-transform:uppercase;color:var(--muted);white-space:nowrap;transform:translateX(-50%);opacity:.8}
.heat{pointer-events:none}

/* Report */
.report{position:fixed;inset:0;z-index:5000;background:var(--sea);overflow:auto;padding-block:max(16px,env(safe-area-inset-top,0px)) max(24px,env(safe-area-inset-bottom,0px));
  padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px))}
.rbar{position:sticky;top:0;z-index:2;display:flex;flex-wrap:wrap;gap:8px;align-items:center;justify-content:space-between;max-width:820px;margin:0 auto 12px;padding:8px 0;background:var(--sea)}
.rbar .ok{font-size:13px;color:var(--accent)}
.doc{max-width:820px;margin:0 auto;background:var(--paper);border:1px solid var(--line);border-radius:4px;padding:36px clamp(18px,5vw,56px) 44px}
.doc .eyebrow{font:700 12px var(--f-disp);letter-spacing:.14em;text-transform:uppercase;color:var(--muted)}
.doc h1{font-size:40px;margin:6px 0 4px}
.doc h3{font:800 20px var(--f-disp);font-stretch:85%;margin:26px 0 8px;padding-top:12px;border-top:2px solid var(--ink)}
.doc p,.doc li{max-width:68ch}
.doc .lead{font-size:17px}
.doc table{width:100%;border-collapse:collapse;font-size:14px;margin:6px 0}
.doc th,.doc td{text-align:left;padding:6px 8px 6px 0;border-bottom:1px solid var(--line);vertical-align:top}
.doc th{color:var(--muted);font-weight:600;font-size:12.5px}
.doc td.num{text-align:right;font-variant-numeric:tabular-nums;font-family:var(--f-mono);font-size:13px}
.tw{overflow-x:auto}
.doc .note{font-size:13px;color:var(--muted)}
.doc .meta{display:flex;flex-wrap:wrap;gap:6px 18px;font-size:13px;color:var(--muted);margin-top:8px}

/* panel tabs, index builder, scatter, map controls */
.ptabs{display:flex;border:1px solid var(--line);border-radius:8px;overflow:hidden}
.ptab{flex:1 1 auto;font:600 13px/1.2 var(--f-body);padding:9px 8px;background:var(--paper);color:var(--muted);border:0;cursor:pointer}
.ptab+.ptab{border-left:1px solid var(--line)}
.ptab[aria-selected="true"]{background:var(--ink);color:var(--paper)}
.score{display:inline-block;min-width:34px;text-align:right;font:700 13px var(--f-mono);font-variant-numeric:tabular-nums}
.list .r{display:block;font-weight:400;font-size:12px;color:var(--muted);white-space:normal}
.list button.two{grid-template-columns:10px 1fr auto;align-items:start}
.list button.two .sw{margin-top:5px}
.presets{display:flex;flex-wrap:wrap;gap:6px;margin:10px 0}
.slider{display:grid;grid-template-columns:1fr auto;gap:2px 10px;padding:8px 0;border-bottom:1px solid var(--line)}
.slider label{font-size:13.5px;font-weight:600}
.slider output{font:12px var(--f-mono);color:var(--muted)}
.slider input{grid-column:1/-1;width:100%;accent-color:var(--accent)}
.slider .m{grid-column:1/-1;font-size:11.5px;color:var(--muted)}
.slider.off label{color:var(--muted)}
.tag{font:600 10.5px var(--f-body);letter-spacing:.04em;text-transform:uppercase;padding:1px 6px;border-radius:4px;background:var(--chip);color:var(--muted);margin-left:6px;vertical-align:1px}
.mv{font:11px var(--f-mono);margin-left:6px}
.mv.up{color:var(--t1)} .mv.dn{color:var(--t0)}
.sc svg{width:100%;height:auto;display:block}
.sc .ax{stroke:var(--line)} .sc text{fill:var(--muted);font:10px var(--f-body)}
.sc .q{fill:var(--t1);fill-opacity:.06}
.sc circle{stroke:var(--ink);stroke-width:.6;cursor:pointer}
.sc circle:hover,.sc circle.sel{stroke-width:2}
.sc .ql{fill:var(--t1);font-weight:700}
.cmp{width:100%;border-collapse:collapse;font-size:13px;margin:8px 0}
.cmp td,.cmp th{padding:4px 6px 4px 0;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}
.cmp th{color:var(--muted);font-weight:600;font-size:12px}
.cmp td.num{text-align:right;font-family:var(--f-mono);font-size:12px;font-variant-numeric:tabular-nums;white-space:nowrap}
.bar{height:6px;border-radius:3px;background:var(--line);overflow:hidden;min-width:50px}
.bar i{display:block;height:100%;background:var(--t1)}
.mapctl{position:absolute;z-index:1000;top:max(12px,env(safe-area-inset-top,0px));right:max(12px,env(safe-area-inset-right,0px));display:flex;flex-wrap:wrap;gap:6px;justify-content:flex-end}
.mapctl button,.mapctl a{font:700 13px var(--f-body);padding:8px 12px;border-radius:8px;border:1px solid var(--line);background:var(--paper);color:var(--ink);cursor:pointer;text-decoration:none;box-shadow:0 4px 12px rgba(0,0,0,.12)}
.mapctl button[aria-pressed="true"]{background:var(--ink);color:var(--paper);border-color:var(--ink)}
.legend .rkey{display:flex;gap:12px;margin-top:6px;font-size:11.5px;color:var(--muted)}
.legend .rkey span{display:inline-flex;gap:5px;align-items:center}
.legend .rkey i{width:16px;height:0;border-top:3px solid var(--c);display:inline-block}
.route-line{stroke-linecap:round}
@media (max-width:860px){
  .app{grid-template-columns:1fr;grid-template-rows:56vh auto;overflow:auto}
  .mapcard{grid-row:1;min-height:56vh}
  .panel{grid-row:2;min-height:70vh}
  .brand span{display:none}
  .legend{min-width:0;bottom:8px;padding:8px 10px}
  .legend .keys{display:none}
  .tiers{grid-template-columns:repeat(3,1fr)}
}
@media (prefers-reduced-motion: reduce){*{transition:none!important}}
</style>

@include('Both.navbar')

<div class="shell">
  <header class="topbar">
    <div class="brand"><b>Maldives Eku_mv</b></div>
    <nav class="nav" aria-label="Sections">
      <button data-nav="map">Map</button><button data-nav="routes">Routes</button><button data-nav="index">Index</button><button data-nav="reports">Reports</button><button data-nav="method">Method</button>
    </nav>
  </header>
  <div class="app">
    <aside class="panel" id="panel">
      <div class="head">
        <div class="filters">
          <select id="atoll" aria-label="Atoll"></select>
          <div class="search"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="11" cy="11" r="7"/><path d="m20 20-3.5-3.5"/></svg><input type="search" id="q" placeholder="Search islands, atolls or routes" aria-label="Search islands, atolls or routes"></div>
        </div>
        <div class="chips" id="lens" role="group" aria-label="Heat lens"></div>
        <div class="tools"><select id="scen" aria-label="Scenario for hospital access"></select><button class="btn" id="rep-scope">Generate report</button></div>
        <p class="lensnote" id="lensnote"></p>
        <div class="tiers" id="tiers" role="group" aria-label="Screening tiers"></div>
        <div class="ptabs" role="tablist" aria-label="Panel views">
          <button class="ptab" role="tab" id="tab-routes" data-tab="routes">Routes</button>
          <button class="ptab" role="tab" id="tab-list" data-tab="list">Ranked islands</button>
          <button class="ptab" role="tab" id="tab-index" data-tab="index">Index builder</button>
          <button class="ptab" role="tab" id="tab-top" data-tab="top">Top 15</button>
          <button class="ptab" role="tab" id="tab-scatter" data-tab="scatter">Population vs service</button>
        </div>
      </div>
      <div class="body" id="body"></div>
    </aside>
    <section class="mapcard" aria-label="Heat map">
      <div id="map" aria-label="Heat map of underserved islands in the Maldives">
        <div class="mapctl"><button id="full-view">Full country</button><button id="routes-tog" aria-pressed="false">Show routes</button><a id="routes-link" href="https://claude.ai/artifact/CmpCrRBbXP7spg4AXvF97n" target="_blank" rel="noopener">Open route map ↗</a></div>
        <div class="legend" id="legend"></div>
      </div>
    </section>
  </div>
