const RUN_DATE = '24 Oct 2026';
const TIERS = [['Tier 1','--t1'],['Tier 2','--t2'],['Tier 3','--t3'],['Not flagged','--t0'],['Not assessed','--tna']];
const TCOL = Object.fromEntries(TIERS);
const CATTXT = {on:'Hospital on the island',road:'Road-linked to hospital',ok:'Same-day return possible',oneway:'One-way only (no same-day return)',far:'Reachable only beyond the time limit',none:'No scheduled journey',na:'Not established'};
const CAPTXT = {on:'Is the atoll capital',road:'Road-linked to capital',ok:'Same-day return possible',oneway:'One-way only (no same-day return)',far:'Reachable only beyond the time limit',none:'No scheduled journey',na:'Not established'};
const HGAP = {on:0,road:0,ok:.12,oneway:.7,far:.85,none:1,na:0};
const LENSES = {
  idx:{label:'Underservice Index',note:'Heat = composite Underservice Index (0 best served, 100 most underserved). Change the weights in Index builder.',w:i=>i._idx==null?0:i._idx/100},
  tier:{label:'Screening tier',note:'Heat = screening tier (Tier 1 hottest). Heat = screening tier (Tier 1 hottest), spread across each atoll from its islands and clipped to the atoll outline.',w:i=>({'Tier 1':1,'Tier 2':.68,'Tier 3':.38,'Not flagged':.06,'Not assessed':0})[i.tier]},
  hosp:{label:'Hospital access gap',note:'Heat = how hard it is to reach an HG2+ hospital and return the same day (2 h max one-way, 4 h at the hospital). Changes with the scenario.',w:(i,s)=>{const c=s==='base'?i.h:(i.scn[s]||i.h);let g=HGAP[c]??0;if(c==='ok'&&i.hd<3)g=.4;return g}},
  scar:{label:'Service scarcity',note:'Heat = scarcity flags: <6 service days, few departures, one route, no alternative if that route is lost.',w:i=>i.tt?i.sf/4:0},
  dep:{label:'Critical dependency',note:'Heat = losing one route leaves no service or removes hospital same-day return.',w:i=>({High:1,Medium:.5,Low:.08})[i.dD]||0},
  pop:{label:'Residents affected',note:'Heat = residents on flagged islands (Tier 1–3), weighted by tier.',w:i=>{const t={'Tier 1':1,'Tier 2':.7,'Tier 3':.4}[i.tier]||0;return t*Math.min(1,Math.sqrt((i.pop||0)/4000))}}
};
const SCNAME = {'base':'Base (RTL + CFN, agreed rules)'};
let state = {route:null, tab:'list', lens:'idx', atoll:'', scen:'base', tiers:new Set(TIERS.map(t=>t[0])), sel:null, q:''};
try{const s=JSON.parse(localStorage.getItem('uim-state')||'null');if(s){state.lens=s.lens||state.lens;state.scen=s.scen||state.scen;state.tab=s.tab||state.tab}}catch(e){}
const css = n => getComputedStyle(document.documentElement).getPropertyValue(n).trim();
const fmt = n => n==null?'–':Math.round(n).toLocaleString('en-US');
const mins = m => m==null?'–':(m>=60?`${Math.floor(m/60)} h ${String(Math.round(m%60)).padStart(2,'0')} min`:`${Math.round(m)} min`);
const esc = s => String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const I = DATA.islands, byId = Object.fromEntries(I.map(i=>[i.id,i]));
const atolls = [...new Set(I.map(i=>i.a))];

/* ---------- Underservice Index ----------
   Each component is turned into a 0–1 "worse than" score: the share of assessed islands that are
   better on that measure. The index is the weighted mean of those scores × 100. */
const INFv=Infinity;
const COMP=[
  {k:'tpk',label:'Weekly trips per 1,000 residents',dir:-1,w:2,f:v=>v.toFixed(1)+' trips',val:i=>i.tt&&i.pop?i.dep/i.pop*1000:null},
  {k:'hosp',label:'Travel time to nearest HG2+ hospital',dir:1,w:3,f:v=>v===INFv?'no same-day journey':mins(v),val:i=>(i.h==='on')?0:(i.h==='road'?(i.hf||15):(i.hf==null?INFv:i.hf))},
  {k:'cap',label:'Travel time to atoll capital',dir:1,w:1,f:v=>v===INFv?'no same-day journey':mins(v),val:i=>(i.c==='on')?0:(i.c==='road'?(i.cf||15):(i.cf==null?INFv:i.cf))},
  {k:'male',label:'Travel time to Malé',dir:1,w:1,f:v=>v===INFv?'no same-day journey':mins(v),val:i=>i.id==='male'?0:(i.male==null?INFv:i.male)},
  {k:'dc',label:'Direct connections (no change of boat)',dir:-1,w:1,f:v=>v+' island'+(v===1?'':'s'),val:i=>i.tt?i.dc:null},
  {k:'canc',label:'Cancellation rate',dir:1,w:0,f:v=>(v*100).toFixed(0)+'%',val:i=>i.cx,tag:'synthetic',note:'From the synthetic FollowMe events log: covers 6 RTL routes only; islands without data score as the median.'},
  {k:'fare',label:'Average fare relative to distance',dir:1,w:0,f:v=>v,val:()=>null,tag:'no data',off:true,note:'No fare table has been supplied yet. Add one and this slider switches on.'}
];
const PRESETS={'Balanced':{tpk:2,hosp:3,cap:1,male:1,dc:1,canc:0},'Healthcare first':{tpk:1,hosp:5,cap:1,male:2,dc:0,canc:0},'Connectivity first':{tpk:4,hosp:1,cap:2,male:1,dc:3,canc:0},'Reliability':{tpk:2,hosp:2,cap:1,male:1,dc:1,canc:4}};
let W=Object.fromEntries(COMP.map(c=>[c.k,c.w]));
try{const s=JSON.parse(localStorage.getItem('uim-w')||'null');if(s)Object.assign(W,s)}catch(e){}
const POOL=I.filter(i=>i.as_);
COMP.forEach(c=>{
  const vals=POOL.map(i=>c.val(i)).filter(v=>v!=null);
  POOL.forEach(i=>{const v=c.val(i);i['_v_'+c.k]=v;
    if(v==null||c.off){i['_s_'+c.k]=null;return}
    let worse=0,tie=0;for(const u of vals){if(u===v)tie++;else if(c.dir>0?u<v:u>v)worse++}
    i['_s_'+c.k]=(worse+tie/2)/vals.length;});
});
function computeIndex(){
  const act=COMP.filter(c=>!c.off&&W[c.k]>0),tot=act.reduce((a,c)=>a+W[c.k],0);
  I.forEach(i=>{if(!i.as_||!tot){i._idx=null;return}
    let s=0;act.forEach(c=>{const v=i['_s_'+c.k];s+=W[c.k]*(v==null?.5:v)});i._idx=Math.round(s/tot*1000)/10});
  const ranked=POOL.filter(i=>i._idx!=null).sort((a,b)=>b._idx-a._idx);ranked.forEach((i,k)=>i._rank=k+1);
}
function balancedRanks(){const keep=W;W=PRESETS['Balanced'];computeIndex();const r=Object.fromEntries(POOL.map(i=>[i.id,i._rank]));W=keep;computeIndex();return r}
let BAL={};
function reasons(i,n=3){
  if(!i.as_)return [];
  return COMP.filter(c=>!c.off&&W[c.k]>0&&i['_s_'+c.k]!=null).map(c=>({c,s:i['_s_'+c.k],x:W[c.k]*i['_s_'+c.k]}))
    .sort((a,b)=>b.x-a.x).filter(r=>r.s>=.6).slice(0,n)
    .map(r=>`${r.c.label}: ${r.c.f(i['_v_'+r.c.k])}, worse than ${Math.round(r.s*100)}% of islands`);
}
computeIndex();BAL=balancedRanks();

/* ---------- map ---------- */
const map = L.map('map',{zoomControl:true,attributionControl:false,minZoom:6,maxZoom:14,zoomSnap:.25}).fitBounds([[-0.75,72.6],[7.15,73.8]]);
const shapes = DATA.shapes.map(s=>L.polygon(s,{className:'atoll-shape',interactive:false}).addTo(map));
DATA.atollC.forEach(([n,c])=>L.marker(c,{interactive:false,icon:L.divIcon({className:'atoll-label',html:esc(n),iconSize:null})}).addTo(map));

// panes: heat over the atoll fill, then reef linework and land, then inhabited islands on top
map.createPane('heat').style.zIndex=405; map.getPane('heat').style.pointerEvents='none';
map.createPane('line').style.zIndex=420; map.getPane('line').style.pointerEvents='none';
map.createPane('isl').style.zIndex=460;
const cv=L.canvas({padding:.4,pane:'line'});
const dec=r=>{const o=[];let x=0,y=0;for(let k=0;k<r.length;k+=2){x+=r[k];y+=r[k+1];o.push([y/1e4,x/1e4])}return o};
const dec5=r=>{const o=[];let a=0,b=0;for(let k=0;k<r.length;k+=2){a+=r[k];b+=r[k+1];o.push([a/1e5,b/1e5])}return o};
const reefs=DATA.reefs.map(r=>L.polygon(dec(r),{renderer:cv,pane:'line',interactive:false,weight:.7,fill:false,color:'#000'}).addTo(map));
const others=DATA.otherPoly.map(r=>L.polygon(dec5(r),{renderer:cv,pane:'line',interactive:false,weight:.5,fillOpacity:1}).addTo(map));
const islR=L.svg({pane:'isl',padding:.4});
const shp={},mkr={};
I.forEach(i=>{
  const ring=DATA.poly[i.id]?dec5(DATA.poly[i.id]):null;
  const tip=()=>`<b>${esc(i.n)}</b> · ${esc(i.a)}<br>${esc(i.tier)} · ${fmt(i.pop)} residents`;
  if(ring){const p=L.polygon(ring,{renderer:islR,pane:'isl',weight:.9,fillOpacity:1});p.bindTooltip(tip,{sticky:true});p.on('click',()=>select(i.id));shp[i.id]=p;i._b=p.getBounds()}
  const m=L.circleMarker([i.lat,i.lon],{renderer:islR,pane:'isl',radius:2,weight:.8,fillOpacity:1});m.bindTooltip(tip,{direction:'right'});m.on('click',()=>select(i.id));mkr[i.id]=m;
});
function bigEnough(i){if(!i._b)return false;const a=map.latLngToContainerPoint(i._b.getSouthWest()),b=map.latLngToContainerPoint(i._b.getNorthEast());return Math.max(Math.abs(b.x-a.x),Math.abs(b.y-a.y))>=7}
function placeIslands(){
  const z=map.getZoom();
  I.forEach(i=>{const big=bigEnough(i),p=shp[i.id],m=mkr[i.id];
    if(big){if(!map.hasLayer(p))p.addTo(map);if(map.hasLayer(m))m.remove()}
    else{if(p&&map.hasLayer(p))p.remove();if(!map.hasLayer(m))m.addTo(map);m.setRadius(Math.max(1.8,Math.min(4,1.4+(z-6)*.7)))}});
  const show=z>=8.5;others.forEach(o=>o.setStyle({opacity:show?1:0,fillOpacity:show?1:0}));
}
map.on('zoomend',placeIslands);

/* ---------- heat surface ----------
   Each assessed island contributes its need value through a Gaussian kernel (sigma 5 km);
   open water far from any island falls back to 0. The surface is painted in stepped classes
   and clipped to the atoll outlines, so nothing spills past an atoll's edge. */
const HEAT=['#2c3fb8','#2f6fd6','#3aa0e6','#7fcdf0','#d6f1d3','#fff3a3','#ffd15c','#fd9a3a','#ec5228','#c0182a'];
const SIGMA_KM=5, K0=.06;
const heatClass=v=>Math.max(0,Math.min(9,Math.floor(Math.max(0,Math.min(.9999,v))*10)));
const Heat=L.Layer.extend({
  onAdd(m){this._m=m;this._c=L.DomUtil.create('canvas','leaflet-zoom-hide');m.getPane('heat').appendChild(this._c);m.on('moveend zoomend resize',this.draw,this);this.draw()},
  draw(){
    const m=this._m;if(!m)return;const sz=m.getSize(),c=this._c,dpr=Math.min(2,window.devicePixelRatio||1);
    L.DomUtil.setPosition(c,m.containerPointToLayerPoint([0,0]));
    c.width=Math.round(sz.x*dpr);c.height=Math.round(sz.y*dpr);c.style.width=sz.x+'px';c.style.height=sz.y+'px';
    const g=c.getContext('2d');g.setTransform(dpr,0,0,dpr,0,0);g.clearRect(0,0,sz.x,sz.y);
    const G=2,W=Math.ceil(sz.x/G),Hh=Math.ceil(sz.y/G),num=new Float32Array(W*Hh),den=new Float32Array(W*Hh);
    const c0=m.getCenter(),mpp=156543.03*Math.cos(c0.lat*Math.PI/180)/Math.pow(2,m.getZoom());
    const sg=SIGMA_KM*1000/mpp/G, R=Math.ceil(sg*3), inv=1/(2*sg*sg);
    for(const i of I){
      if(i.tier==='Not assessed'||!visible(i))continue;
      const p=m.latLngToContainerPoint([i.lat,i.lon]),cx=p.x/G,cy=p.y/G;if(cx<-R||cy<-R||cx>W+R||cy>Hh+R)continue;
      const w=Math.max(0,Math.min(1,weight(i)));
      const x0=Math.max(0,Math.floor(cx-R)),x1=Math.min(W-1,Math.ceil(cx+R)),y0=Math.max(0,Math.floor(cy-R)),y1=Math.min(Hh-1,Math.ceil(cy+R));
      for(let y=y0;y<=y1;y++){const dy=y-cy;for(let x=x0;x<=x1;x++){const dx=x-cx,k=Math.exp(-(dx*dx+dy*dy)*inv);if(k<1e-3)continue;const j=y*W+x;num[j]+=w*k;den[j]+=k}}
    }
    const off=document.createElement('canvas');off.width=W;off.height=Hh;const og=off.getContext('2d'),img=og.createImageData(W,Hh),d=img.data;
    const RGB=HEAT.map(h=>[1,3,5].map(k=>parseInt(h.slice(k,k+2),16)));
    for(let j=0;j<W*Hh;j++){const v=num[j]/(den[j]+K0),col=RGB[heatClass(v)];d[j*4]=col[0];d[j*4+1]=col[1];d[j*4+2]=col[2];d[j*4+3]=255}
    og.putImageData(img,0,0);
    g.save();g.beginPath();
    for(const s of DATA.shapes){s.forEach(([la,lo],k)=>{const q=m.latLngToContainerPoint([la,lo]);k?g.lineTo(q.x,q.y):g.moveTo(q.x,q.y)});g.closePath()}
    g.clip();g.imageSmoothingEnabled=false;g.drawImage(off,0,0,W*G,Hh*G);g.restore();
    // crisp atoll edge
    g.strokeStyle=css('--ink');g.globalAlpha=.55;g.lineWidth=1;
    for(const s of DATA.shapes){g.beginPath();s.forEach(([la,lo],k)=>{const q=m.latLngToContainerPoint([la,lo]);k?g.lineTo(q.x,q.y):g.moveTo(q.x,q.y)});g.closePath();g.stroke()}
    g.globalAlpha=1;
  }
});
const heat=new Heat().addTo(map);
// scheduled routes overlay (straight links between consecutive stops, width by weekly sailings)
map.createPane('routes').style.zIndex=440;
const routeLayer=L.layerGroup();
DATA.routeLines.forEach(r=>r.seg.forEach(([a,b,c,d,n])=>{
  const pl=L.polyline([[a,b],[c,d]],{pane:'routes',className:'route-line',weight:Math.min(5,1+Math.log2(1+n)/1.6),opacity:.85,color:'#000',dashArray:r.s==='CFN'?'5 4':null});
  pl._src=r.s;pl._key=r.k;pl.bindTooltip(`<b>${esc(r.k)}</b> ${esc(r.t)}<br>${n} sailing(s)/week on this link`,{sticky:true});routeLayer.addLayer(pl)}));
let showRoutes=false;
function styleRoutes(){const a=css('--rtl'),b=css('--cfn');routeLayer.eachLayer(l=>{const on=!state.route||l._key===state.route;l.setStyle({color:l._src==='CFN'?b:a,opacity:on?.9:.12});if(on&&state.route)l.bringToFront()})}

function weight(i){return LENSES[state.lens].w(i,state.scen)}
function visible(i){return state.tiers.has(i.tier)&&(!state.atoll||i.a===state.atoll)&&(!state.q||(i.n+' '+i.a).toLowerCase().includes(state.q))}
function render(){
  try{localStorage.setItem('uim-state',JSON.stringify({lens:state.lens,scen:state.scen,tab:state.tab}))}catch(e){}
  const edge=css('--ink'),land=css('--land'),landE=css('--land-edge');
  styleRoutes();if(showRoutes&&!map.hasLayer(routeLayer))routeLayer.addTo(map);if(!showRoutes&&map.hasLayer(routeLayer))routeLayer.remove();
  const rt=document.getElementById('routes-tog');rt.setAttribute('aria-pressed',showRoutes);rt.textContent=showRoutes?'Hide routes':'Show routes';
  document.querySelectorAll('.ptab').forEach(b=>b.setAttribute('aria-selected',b.dataset.tab===state.tab));
  reefs.forEach(p=>p.setStyle({color:css('--ink'),opacity:.18}));
  others.forEach(o=>o.setStyle({color:landE,fillColor:land}));
  placeIslands();
  I.forEach(i=>{const v=visible(i),sel=state.sel===i.id,st={color:edge,weight:sel?2.4:.9,opacity:v?(sel?1:.85):.25,fillColor:i.tier==='Not assessed'?css('--tna'):land,fillOpacity:v?1:.4};
    [shp[i.id],mkr[i.id]].forEach(l=>{if(l){l.setStyle(st);if(sel&&map.hasLayer(l))l.bringToFront()}})});
  heat.draw();
