  document.getElementById('lensnote').textContent=LENSES[state.lens].note;
  document.getElementById('scen').disabled=state.lens!=='hosp';
  renderTiers();renderLegend();
  document.querySelectorAll('[data-nav]').forEach(b=>{const cur={routes:'routes',index:'index',top:'index'}[state.tab]||'map';b.toggleAttribute('aria-current',b.dataset.nav===cur);if(b.dataset.nav===cur)b.setAttribute('aria-current','page')});
