  if(state.sel)renderDetail(byId[state.sel]);else if(state.tab==='routes')renderRoutes();else if(state.tab==='index')renderIndex();else if(state.tab==='top')renderTop();else if(state.tab==='scatter')renderScatter();else renderList();
}
function renderTiers(){
