function rank(a,b){if(state.lens==='idx'){return ((b._idx??-1)-(a._idx??-1))||((b.pop||0)-(a.pop||0))}
  const o={'Tier 1':0,'Tier 2':1,'Tier 3':2,'Not flagged':3,'Not assessed':4};return (o[a.tier]-o[b.tier])||(weight(b)-weight(a))||((b.pop||0)-(a.pop||0))}
function idxColor(v){return v==null?'var(--tna)':HEAT[Math.max(0,Math.min(9,Math.floor(Math.min(.9999,v/100)*10)))]}
