     :`<li><button data-id="${i.id}" style="--c:var(${TCOL[i.tier]})"><span class="sw"></span><span class="t">${esc(i.n)}<small>${esc(i.a)}</small></span><span class="n">${fmt(i.pop)}</span></button></li>`).join('')}</ul>
   <div class="foot"><p>Method test, ${RUN_DATE}. Scheduled RTL/CFN ferries only; hospital = HG2 and above. Islands missing from the route documents are “Not assessed”, never zero ferries.</p>
   <p>Rules: 30 min transfer · 2 h max to hospital · 4 h max to atoll capital · same-day return with 4 h at the destination.</p></div>`;
}
const RL=DATA.routeLines.map(r=>{const c=DATA.routes.find(x=>x.r===r.k)||{};return Object.assign({},r,{ph:c.ph||0,pa:c.pa||0,names:r.ids.map(id=>byId[id]?byId[id].n:id)})});
function routeVisible(r){return (!state.atoll||r.ids.some(id=>byId[id]&&byId[id].a===state.atoll))&&(!state.q||(r.k+' '+r.t+' '+r.names.join(' ')).toLowerCase().includes(state.q))}
