     <span class="t" style="white-space:normal">${esc(r.names.join(' – '))}<span class="code">${esc(r.k)}</span>
     <span class="r">${r.ns} stops · ${r.nmi} nmi · ${r.lw} legs/week${r.fm?` · ${fmt(r.fm)} trips in events log${r.cx!=null?`, ${Math.round(r.cx*100)}% days without a sailing`:''}`:''}${r.unres?' · <b>1 stop unresolved in crosswalk</b>':''}${r.ph?` · <b style="color:var(--t1)">${fmt(r.ph)} residents lose hospital same-day return if cut</b>`:r.pa?` · ${fmt(r.pa)} residents left without service if cut`:''}</span></span>
     <span class="n">${esc(r.s)}</span></button></li>`).join('')}</ul>`;
