}
function renderScatter(){
  const xs=POOL.filter(i=>visible(i)&&i.pop&&i.tt&&i.dep);
  const Wd=360,Hd=300,ml=40,mr=10,mt=12,mb=34,lx=v=>Math.log10(v),X0=lx(100),X1=lx(200000),Y0=lx(.5),Y1=lx(300);
  const sx=v=>ml+(lx(v)-X0)/(X1-X0)*(Wd-ml-mr),sy=v=>Hd-mb-(lx(Math.max(.5,Math.min(300,v)))-Y0)/(Y1-Y0)*(Hd-mt-mb);
  const tpk=i=>i.dep/i.pop*1000,med=a=>{const s=[...a].sort((x,y)=>x-y);return s[Math.floor(s.length/2)]};
  const mp=med(xs.map(i=>i.pop)),mt_=med(xs.map(tpk));
  const xt=[100,1000,10000,100000].map(v=>`<line class="ax" x1="${sx(v)}" x2="${sx(v)}" y1="${mt}" y2="${Hd-mb}"/><text x="${sx(v)}" y="${Hd-mb+14}" text-anchor="middle">${v>=1000?v/1000+'k':v}</text>`).join('');
  const yt=[1,10,100].map(v=>`<line class="ax" x1="${ml}" x2="${Wd-mr}" y1="${sy(v)}" y2="${sy(v)}"/><text x="${ml-5}" y="${sy(v)+3}" text-anchor="end">${v}</text>`).join('');
  const pts=xs.sort((a,b)=>(a._idx??0)-(b._idx??0)).map(i=>`<circle data-id="${i.id}" class="${state.sel===i.id?'sel':''}" cx="${sx(i.pop).toFixed(1)}" cy="${sy(tpk(i)).toFixed(1)}" r="${(3+Math.sqrt(i.pop)/40).toFixed(1)}" fill="${idxColor(i._idx)}"><title>${esc(i.n)} (${esc(i.a)}): ${fmt(i.pop)} residents, ${tpk(i).toFixed(1)} weekly trips per 1,000, index ${i._idx}</title></circle>`).join('');
  const hot=xs.filter(i=>i.pop>=mp&&tpk(i)<=mt_).sort((a,b)=>b.pop-a.pop);
  document.getElementById('body').innerHTML=`<div style="margin-top:10px" class="sc">
    <p class="lbl">Population vs weekly trips per 1,000 residents</p>
    <svg viewBox="0 0 ${Wd} ${Hd}" role="img" aria-label="Scatter of island population against weekly ferry trips per 1,000 residents">
      <rect class="q" x="${sx(mp)}" y="${sy(mt_)}" width="${Wd-mr-sx(mp)}" height="${Hd-mb-sy(mt_)}"/>
      ${xt}${yt}
      <line class="ax" x1="${sx(mp)}" x2="${sx(mp)}" y1="${mt}" y2="${Hd-mb}" stroke-dasharray="3 3"/><line class="ax" x1="${ml}" x2="${Wd-mr}" y1="${sy(mt_)}" y2="${sy(mt_)}" stroke-dasharray="3 3"/>
      <text class="ql" x="${Wd-mr-4}" y="${Hd-mb-6}" text-anchor="end">High population, low service</text>
      <text x="${(Wd+ml)/2}" y="${Hd-4}" text-anchor="middle">Population 2022 (log scale)</text>
      <text transform="translate(11 ${(Hd-mb+mt)/2}) rotate(-90)" text-anchor="middle">Weekly trips per 1,000 (log)</text>
      ${pts}
    </svg>
    <p class="lensnote" style="min-height:0;margin-top:6px">Dashed lines are the medians (${fmt(mp)} residents; ${mt_.toFixed(1)} trips per 1,000). Dot colour is the Underservice Index; size is population. Click a dot for details.</p>
    <p class="lbl" style="margin-top:12px">${hot.length} islands in the shaded quadrant</p>
    <ul class="list">${hot.map(i=>`<li><button data-id="${i.id}" style="--c:${idxColor(i._idx)}"><span class="sw"></span><span class="t">${esc(i.n)}<small>${esc(i.a)} · ${tpk(i).toFixed(1)} trips/1,000</small></span><span class="n">${fmt(i.pop)}</span></button></li>`).join('')}</ul></div>`;
}
function compTable(i){
  return `<table class="cmp"><tr><th>Component</th><th>Value</th><th>Worse than</th><th>Weight</th></tr>${COMP.map(c=>{const v=i['_v_'+c.k],s=i['_s_'+c.k];
    return `<tr><td>${esc(c.label)}${c.tag?`<span class="tag">${esc(c.tag)}</span>`:''}</td><td class="num">${c.off?'no data':(v==null?'no data':esc(c.f(v)))}</td><td><div class="bar"><i style="width:${s==null?0:Math.round(s*100)}%"></i></div></td><td class="num">${c.off?'–':W[c.k]}</td></tr>`}).join('')}</table>`;
}
function dim(k,v){return `<div class="dim ${esc(v)}"><span>${k}</span><b>${esc(v)}</b></div>`}
function renderDetail(i){
