     <dt>Evidence</dt><dd>${esc(i.ev)}</dd>
   </dl>
   <div class="actions"><button class="btn" id="rep-isl">Generate island report</button><button class="btn ghost" id="rep-at">Atoll report: ${esc(i.a)}</button></div></div>`;
}
function select(id){state.sel=id;const i=byId[id];render();if(i._b)map.flyToBounds(i._b.pad(1.2),{maxZoom:14,duration:.6});else map.setView([i.lat,i.lon],Math.max(map.getZoom(),11));}

/* ---------- reports ---------- */
const ORDER={'Tier 1':0,'Tier 2':1,'Tier 3':2,'Not flagged':3,'Not assessed':4};
function reviewPoints(i){
  const p=[];
  if(!i.as_) return [/crosswalk/.test(i.ev)?'Resolve the Hulhumeedhoo stop in the stop crosswalk (terminal-level evidence or a composite-place node) so these islands can be assessed.':'Add a crosswalked RTL/CFN stop for this island so it can be assessed.'];
  if(['oneway','far','none'].includes(i.h)) p.push(i.h==='oneway'?'Check whether a later return sailing (or an earlier arrival) would give 4 hours at the hospital and a same-day return.':'Review how residents reach an HG2+ hospital today (medical launch, private speedboat, flight) and whether a scheduled connection is feasible.');
  if(i.tt&&i.days<6) p.push(`Service runs on ${i.days} day(s)/week; review whether additional operating days are possible.`);
  if(i.svc.length<=1&&i.tt) p.push('Only one documented route serves the island; identify a fallback service if it is suspended.');
  if(i.cr&&i.sa===0) p.push(`Losing ${i.cr} would leave the island with no scheduled service.`);
  if(i.c && ['oneway','far','none'].includes(i.c)) p.push(`No same-day return to the atoll capital (${i.cap}) within 4 hours.`);
  if(!i.rs) p.push('The hospital result changes between the RTL route sheets and the CFN schedule; confirm which timetable MTCC currently runs.');
  if(!i.rr) p.push('The hospital result is sensitive to the transfer or time-at-destination rule.');
  if(['Alifu Alifu','Alifu Dhaalu','Faafu','Meemu','Vaavu'].includes(i.a)&&['far','none','oneway'].includes(i.h)) p.push('The atoll has only a Grade 1 hospital; under the “any atoll hospital” scenario the result is: '+CATTXT[i.scn['Any atoll hospital (HG1+)']||'na']+'.');
  return p.length?p:['No screening flags under the agreed rules.'];
}
function islandReport(i){
  const scen=['base',...DATA.scen].map(s=>`<tr><td>${esc(SCNAME[s]||s)}</td><td>${esc(CATTXT[s==='base'?i.h:i.scn[s]])}</td></tr>`).join('');
  const svc=i.svc.map(s=>`<tr><td class="mono">${esc(s[0])}</td><td>${esc(s[1])}</td></tr>`).join('');
  const lead=i.as_?`${i.n} (${i.a}; ${fmt(i.pop)} residents in the 2022 census) is screened <b>${i.tier}</b>${i.why?': '+esc(i.why)+'.':'.'}`:`${i.n} (${i.a}) does not appear in the RTL route sheets or the CFN schedule, so it is marked not assessed rather than given zero ferries.`;
  return `<p class="eyebrow">Island accessibility and service gap report</p><h1>${esc(i.n)}</h1>
   <div class="meta"><span>${esc(i.a)}</span><span>Screening run ${RUN_DATE} (method test)</span><span>Evidence: ${esc(i.ev)}</span></div>
   <h3>Summary</h3><p class="lead">${lead}</p>
   <table><tr><th>Assessment</th><th>Level</th></tr><tr><td>Service scarcity</td><td>${esc(i.dS)}</td></tr><tr><td>Critical dependency</td><td>${esc(i.dD)}</td></tr><tr><td>Essential-service accessibility</td><td>${esc(i.dA)}</td></tr><tr><td>Population exposure</td><td>${esc(i.dP)}</td></tr></table>
   ${i.as_?`<h3>Underservice Index</h3><p>Score <b>${i._idx}</b> out of 100 (rank ${i._rank} of ${POOL.length} assessed islands; higher means more underserved), using the weights currently set in the index builder.</p><div class="tw">${compTable(i)}</div>`:''}
   <h3>Island profile</h3><div class="tw"><table>
   <tr><td>Population 2022 (census)</td><td class="num">${fmt(i.pop)}</td></tr>
   <tr><td>Population density (residents per ha)</td><td class="num">${i.den??'–'}</td></tr>
   <tr><td>Registered under-18 share, 2025</td><td class="num">${i.u18!=null?(i.u18*100).toFixed(1)+'%':'–'}</td></tr></table></div>
   <h3>Scheduled ferry service</h3><div class="tw"><table>
   <tr><td>Scheduled departures per week</td><td class="num">${i.dep??'–'}</td></tr>
   <tr><td>Days with service per week</td><td class="num">${i.days??'–'}</td></tr>
   <tr><td>Operating days</td><td class="num">${esc(i.sd||'–')}</td></tr>
   <tr><td>Distinct ferry services</td><td class="num">${i.tt?i.svc.length:'–'}</td></tr></table></div>
   ${svc?`<div class="tw"><table><tr><th>Service</th><th>Route as published</th></tr>${svc}</table></div>`:''}
   <h3>Access to essential services</h3><div class="tw"><table>
   <tr><th></th><th>HG2+ hospital</th><th>Atoll capital</th></tr>
   <tr><td>Result</td><td>${esc(CATTXT[i.h])}</td><td>${esc(CAPTXT[i.c])}</td></tr>
   <tr><td>Destination</td><td>${esc(i.hdest||'–')}</td><td>${esc(i.cap||'–')}</td></tr>
   <tr><td>Days/week with same-day return</td><td>${i.hd??'–'}${i.hds&&i.hds!=='ALL'?' ('+esc(i.hds)+')':''}</td><td>${i.cd??'–'}</td></tr>
   <tr><td>Fastest scheduled one-way journey</td><td>${mins(i.hf)}</td><td>${mins(i.cf)}</td></tr></table></div>
   <p class="note">Same-day return requires a one-way journey of at most 2 h (hospital) or 4 h (capital), at least 4 h at the destination, and 30 min for any change of vessel.</p>
   <h3>Route-loss resilience</h3>
   <p>${i.cr?`The most critical service is <span class="mono">${esc(i.cr)}</span> (${esc(i.crt)}). If it is removed, the island keeps ${i.sa} service day(s) per week and a same-day hospital return on ${i.hl} day(s).`:'No scheduled service to simulate.'}</p>
   <h3>Sensitivity of the hospital result</h3><div class="tw"><table><tr><th>Scenario</th><th>Hospital access</th></tr>${scen}</table></div>
   <h3>Points for review</h3><ul>${reviewPoints(i).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>
   <h3>Sources and limits</h3><p class="note">MTCC RTL route sheets (undated) and CFN ferry schedule (1 Aug 2026); MBS Census 2022 Tables 3.3 and 1.5; registered population Table 3.5 (2025); Ministry of Health register of health establishments. Scheduled public ferries only: private speedboats, flights and medical launches are outside this screening. Ridership and trip-delivery data are not yet included.</p>`;
}
function groupReport(title, xs){
  xs=[...xs].sort(rank);
  const cnt=TIERS.map(([t])=>{const g=xs.filter(i=>i.tier===t);return `<tr><td>${t}</td><td class="num">${g.length}</td><td class="num">${fmt(g.reduce((a,i)=>a+(i.pop||0),0))}</td></tr>`}).join('');
  const flagged=xs.filter(i=>/Tier/.test(i.tier));
  const rows=flagged.map(i=>`<tr><td>${esc(i.n)}</td><td>${esc(i.a)}</td><td>${esc(i.tier)}</td><td class="num">${i._idx??'–'}</td><td class="num">${fmt(i.pop)}</td><td class="num">${i.days??'–'}</td><td>${esc(CATTXT[i.h])}</td><td>${esc(i.why)}</td></tr>`).join('');
  const ids=new Set(xs.map(i=>i.id));
  const rts=DATA.routes.filter(r=>(r.lh+';'+r.la).split(';').map(s=>s.trim()).some(s=>ids.has(s))).slice(0,10)
    .map(r=>`<tr><td class="mono">${esc(r.r)}</td><td>${esc(r.t)}</td><td class="num">${fmt(r.pa)}</td><td class="num">${fmt(r.ph)}</td></tr>`).join('');
  const noH=xs.filter(i=>['oneway','far','none'].includes(i.h));
  return `<p class="eyebrow">Underserved islands report</p><h1>${esc(title)}</h1>
   <div class="meta"><span>${xs.length} islands</span><span>${fmt(xs.reduce((a,i)=>a+(i.pop||0),0))} residents (census 2022)</span><span>Screening run ${RUN_DATE} (method test)</span></div>
   <h3>Summary</h3><p class="lead">${flagged.length} of ${xs.length} islands are flagged (Tier 1–3). ${noH.length} island(s), home to ${fmt(noH.reduce((a,i)=>a+(i.pop||0),0))} residents, have no same-day scheduled return to an HG2+ hospital within 2 hours.</p>
   <div class="tw"><table><tr><th>Tier</th><th>Islands</th><th>Residents</th></tr>${cnt}</table></div>
   <h3>Flagged islands</h3>${rows?`<div class="tw"><table><tr><th>Island</th><th>Atoll</th><th>Tier</th><th>Index</th><th>Residents</th><th>Service days</th><th>Hospital access</th><th>Reasons</th></tr>${rows}</table></div>`:'<p>No islands flagged.</p>'}
   <h3>Most critical routes</h3>${rts?`<div class="tw"><table><tr><th>Service</th><th>Route</th><th>Residents left with no service if lost</th><th>Residents losing hospital same-day return</th></tr>${rts}</table></div>`:'<p>No route losses affect these islands.</p>'}
   <h3>How to read this</h3><p class="note">Tier 1: no same-day return to an HG2+ hospital and dependence on one route. Tier 2: no same-day hospital return, or two or more scarcity flags without local hospital care. Tier 3: one scarcity flag or no same-day return to the atoll capital. Rules: 30 min transfer, 2 h max to hospital, 4 h max to capital, 4 h at the destination. Scheduled RTL/CFN ferries only; islands absent from the route documents are not assessed.</p>`;
}
function methodDoc(){
  return `<p class="eyebrow">Method</p><h1>How the screening works</h1>
   <div class="meta"><span>Method test, ${RUN_DATE}</span><span>190 inhabited islands</span></div>
   <h3>Data</h3><ul><li>Routing uses two datasets only: the stop crosswalk (CFN/RTL registry closeout master: 686 stop records, 684 approved) for every stop's identity, and the FollowMe events log (synthetic, 2023–2025) for observed trips and cancellations. Sailing times are the schedule times the crosswalk is keyed to (RTL route sheets and CFN schedule of 1 August 2026, 864 legs). No road or causeway links are added.</li><li>The crosswalk leaves S. Hulhumeedhoo unresolved (review required), so Hulhudhoo and Meedhoo are not assessed; FollowMe routes R2C1 and R2C2 have no crosswalk entry and are not routed.</li><li>Population: MBS Census 2022 (Tables 3.3 and 1.5); registered population by age, 2025 (Table 3.5).</li><li>Hospitals: Ministry of Health register; HG2 and above (Hospital Grade 2/3, General, Tertiary).</li><li>Island outlines: OpenStreetMap (ODbL). Fares: not yet supplied.</li></ul>
   <h3>Journey rules</h3><ul><li>30 min minimum transfer when changing vessel.</li><li>2 h maximum one-way to a hospital (Lancet Commission benchmark); 4 h to the atoll capital.</li><li>Same-day return with at least 4 h at the destination; days per week with such a return are counted.</li></ul>
   <h3>Screening tiers</h3><p>Tier 1: no same-day return to an HG2+ hospital within 2 h and dependence on a single route. Tier 2: no same-day hospital return, or two or more scarcity flags without local hospital care. Tier 3: one scarcity flag or no same-day return to the atoll capital. Islands missing from the route documents are not assessed, never given zero ferries.</p>
   <h3>Underservice Index</h3><p>Each component becomes a 0–1 score: the share of assessed islands that do better. The index is the weighted mean of those scores × 100. Current weights: ${COMP.filter(c=>!c.off).map(c=>esc(c.label)+' '+W[c.k]).join(', ')}.</p>
   <h3>Known limits</h3><ul><li>Whether CFN replaces or runs alongside RTL is unconfirmed; both are combined in the base case.</li><li>Scheduled public ferries only: no private speedboats, flights or medical launches.</li><li>Large hubs score poorly on trips per 1,000 residents because many residents share few public ferries.</li></ul>`;
}
function toText(el){
  const out=[];el.querySelectorAll('h1,h3,p,li,table').forEach(n=>{
    if(n.closest('table')&&n.tagName!=='TABLE')return;
    if(n.tagName==='H1')out.push('# '+n.innerText);else if(n.tagName==='H3')out.push('\n## '+n.innerText);
    else if(n.tagName==='LI')out.push('- '+n.innerText);
    else if(n.tagName==='TABLE'){const rows=[...n.rows].map(r=>'| '+[...r.cells].map(c=>c.innerText.replace(/\|/g,'/')).join(' | ')+' |');if(rows.length){const k=n.rows[0].cells.length;rows.splice(1,0,'|'+' --- |'.repeat(k));}out.push(rows.join('\n'))}
    else if(!n.closest('li'))out.push(n.innerText)});
  return out.join('\n\n');
}
function openReport(html){
  const R=document.getElementById('report');
  R.innerHTML=`<div class="rbar"><button class="btn ghost" id="rclose">← Back to map</button><span class="ok" id="rmsg" role="status"></span><button class="btn" id="rcopy">Copy report as text</button></div><article class="doc" id="doc">${html}</article><textarea id="rfall" aria-label="Report text" hidden style="max-width:820px;width:100%;height:240px;margin:12px auto;display:block"></textarea>`;
  R.hidden=false;R.scrollTop=0;document.getElementById('rclose').focus();
}
document.addEventListener('click',e=>{
  const t=e.target.closest('button');if(!t)return;
  if(t.dataset.k){state.lens=t.dataset.k;render()}
  else if(t.dataset.tab){state.tab=t.dataset.tab;state.sel=null;if(state.tab==='routes')showRoutes=true;render()}
  else if(t.dataset.preset){Object.assign(W,PRESETS[t.dataset.preset]);try{localStorage.setItem('uim-w',JSON.stringify(W))}catch(e){};computeIndex();render()}
  else if(t.id==='routes-tog'){showRoutes=!showRoutes;if(!showRoutes)state.route=null;render()}
  else if(t.dataset.route){focusRoute(t.dataset.route)}
  else if(t.dataset.nav){const n=t.dataset.nav;
    if(n==='map'){state.tab='list';state.sel=null;render()}
    else if(n==='routes'){state.tab='routes';state.sel=null;showRoutes=true;render()}
    else if(n==='index'){state.tab='index';state.sel=null;render()}
    else if(n==='reports'){openReport(groupReport('Maldives: flagged islands',I))}
    else if(n==='method'){openReport(methodDoc())}}
  else if(t.id==='full-view'){map.flyToBounds([[-0.75,72.6],[7.15,73.8]],{duration:.6})}
  else if(t.dataset.t){const only=state.tiers.size===1&&state.tiers.has(t.dataset.t);state.tiers=only?new Set(TIERS.map(x=>x[0])):new Set([t.dataset.t]);state.sel=null;render()}
  else if(t.dataset.id){select(t.dataset.id)}
  else if(t.id==='back'){state.sel=null;render()}
  else if(t.id==='rep-isl'){openReport(islandReport(byId[state.sel]))}
  else if(t.id==='rep-at'){const a=byId[state.sel].a;openReport(groupReport(a,I.filter(i=>i.a===a)))}
  else if(t.id==='rep-scope'){openReport(state.atoll?groupReport(state.atoll,I.filter(i=>i.a===state.atoll)):groupReport('Maldives: flagged islands',I))}
  else if(t.id==='rclose'){document.getElementById('report').hidden=true}
  else if(t.id==='rcopy'){const txt=toText(document.getElementById('doc')),msg=document.getElementById('rmsg');
    const fb=()=>{const ta=document.getElementById('rfall');ta.hidden=false;ta.value=txt;ta.focus();ta.select();msg.textContent='Text selected below — press Ctrl/Cmd+C to copy.'};
    try{navigator.clipboard.writeText(txt).then(()=>msg.textContent='Report copied as Markdown text.',fb)}catch(err){fb()}}
});
document.addEventListener('click',e=>{const c=e.target.closest('.sc circle');if(c)select(c.dataset.id)});
document.addEventListener('input',e=>{const k=e.target.dataset&&e.target.dataset.w;if(!k)return;W[k]=+e.target.value;
  document.getElementById('o-'+k).textContent=W[k];try{localStorage.setItem('uim-w',JSON.stringify(W))}catch(err){}
  computeIndex();heat.draw();renderLegend();fillTop();
  document.querySelectorAll('[data-preset]').forEach(b=>b.setAttribute('aria-pressed',JSON.stringify(PRESETS[b.dataset.preset])===JSON.stringify(Object.fromEntries(COMP.filter(c=>!c.off).map(c=>[c.k,W[c.k]])))))});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!document.getElementById('report').hidden)document.getElementById('report').hidden=true});

/* ---------- controls ---------- */
document.getElementById('q').addEventListener('input',e=>{state.q=e.target.value.trim().toLowerCase();state.sel=null;render()});
document.getElementById('lens').innerHTML=Object.entries(LENSES).map(([k,v])=>`<button class="chip" data-k="${k}" aria-pressed="false">${v.label}</button>`).join('');
const at=document.getElementById('atoll');at.innerHTML='<option value="">All atolls</option>'+atolls.map(a=>`<option>${esc(a)}</option>`).join('');
at.onchange=e=>{state.atoll=e.target.value;state.sel=null;render();
  const xs=I.filter(i=>!state.atoll||i.a===state.atoll);map.fitBounds(L.latLngBounds(xs.map(i=>[i.lat,i.lon])).pad(.25),{maxZoom:10})};
const sc=document.getElementById('scen');sc.innerHTML=['base',...DATA.scen].map(s=>`<option value="${esc(s)}">${esc(SCNAME[s]||s)}</option>`).join('');sc.value=state.scen;
sc.onchange=e=>{state.scen=e.target.value;render()};
sc.title='Scenario (applies to the hospital access lens)';
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>render());
new MutationObserver(()=>render()).observe(document.documentElement,{attributes:true,attributeFilter:['data-theme']});
render();
</script>

</body></html>